(196052, 11191, 5728, '<td valign="top">I knew this was a great photo from looking at the thumbnail, and when I clicked on it I loved it even more. Great!</td>', 'I knew this was a great photo from looking at the thumbnail, and when I clicked on it I loved it even more. Great!', '2003-01-20 16:36:52.000000', NULL, 1),
(196059, 11177, 4648, '<td valign="top">What''s the blue on the glass by the cookie?  First thing I saw.  Good choice of background.  Looks like taken with camera at an angle, good job.  Great focus and cropping.  I like the frame and think it adds to this photo, usually don''t.  Great job.  Would be worth an 8.</td>', 'What''s the blue on the glass by the cookie?  First thing I saw.  Good choice of background.  Looks like taken with camera at an angle, good job.  Great focus and cropping.  I like the frame and think it adds to this photo, usually don''t.  Great job.  Would be worth an 8.', '2003-01-20 16:44:51.000000', NULL, 1),
(196060, 11187, 2363, '<td valign="top">My favourite photo this week. I wanted to do a photo of milk bottles too, but couldn''t get hold of any - we get all our milk from the supermarket round here. Like the water droplets on the bottles.</td>', 'My favourite photo this week. I wanted to do a photo of milk bottles too, but couldn''t get hold of any - we get all our milk from the supermarket round here. Like the water droplets on the bottles.', '2003-01-20 16:46:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(196062, 11305, 4648, '<td valign="top">Good idea just needs better execution.  Would have come across better if you couldn''t see the seem between the table and wall.  As is, you can see that the camera was tilted, not the glass.  Good attempt.  Everything in focus with nice cropping.  Like the "coke'' glass idea.  Still worth a 7 for the photograph quality.</td>', 'Good idea just needs better execution.  Would have come across better if you couldn''t see the seem between the table and wall.  As is, you can see that the camera was tilted, not the glass.  Good attempt.  Everything in focus with nice cropping.  Like the "coke'' glass idea.  Still worth a 7 for the photograph quality.', '2003-01-20 16:48:26.000000', NULL, 1),
(196065, 11247, 2363, '<td valign="top">I like the posterisation - it works wel, particularly on the biscuits. Just a shame the background isn''t completely black.</td>', 'I like the posterisation - it works wel, particularly on the biscuits. Just a shame the background isn''t completely black.', '2003-01-20 16:51:02.000000', NULL, 1),
(196067, 11229, 4648, '<td valign="top">What does this have to do with "Got Milk" except maybe for grating cheese.  If that''s it, it needs some cheese.  To me it''s too much of a stretch to say it met the challenge.  But it is a really clear and sharp close-up of a grater.  All I would be able to give it for the challenge is a 4 though.</td>', 'What does this have to do with "Got Milk" except maybe for grating cheese.  If that''s it, it needs some cheese.  To me it''s too much of a stretch to say it met the challenge.  But it is a really clear and sharp close-up of a grater.  All I would be able to give it for the challenge is a 4 though.', '2003-01-20 16:52:30.000000', NULL, 1),
(196071, 11140, 2363, '<td valign="top">Love the depth of field.</td>', 'Love the depth of field.', '2003-01-20 16:55:04.000000', NULL, 1),
(196073, 11288, 2363, '<td valign="top">Interesting mottled cheese.</td>', 'Interesting mottled cheese.', '2003-01-20 16:55:55.000000', NULL, 1),
(196077, 11202, 2363, '<td valign="top">Heh, love the cheese on the rim of the glass.</td>', 'Heh, love the cheese on the rim of the glass.', '2003-01-20 16:56:53.000000', NULL, 1),
(196078, 11189, 4648, '<td valign="top">Looks like a baptism we did in Khazaksthan in 50 degree temperature.  This must be something simular to be dressed this way on an obviously cold day.  Great photo of the people.  Love the colors, the focus, the cropping the composition, but wouldn''t know it was about milk without the title.  I believe to fit the challenge it must show the challenge without the title.  The best I could give it would be a 4.</td>', 'Looks like a baptism we did in Khazaksthan in 50 degree temperature.  This must be something simular to be dressed this way on an obviously cold day.  Great photo of the people.  Love the colors, the focus, the cropping the composition, but wouldn''t know it was about milk without the title.  I believe to fit the challenge it must show the challenge without the title.  The best I could give it would be a 4.', '2003-01-20 16:57:21.000000', NULL, 1),
(196091, 11204, 4648, '<td valign="top">Wish I knew what all kinds of cheese these were.   Hope I can explain this so you can understand.  It''s a little "dull", making it appear dark when it is not dark.  The colors are all dead or dull colors starting with the table.  To have gotten all of the wine bottle, the only thing with any life in the color, in you would have added more dead empty space in the top right corner.  It''s not that it''s a bad photo, it''s just not a really good photo, in spite of the good technical qualities you have.  I hope this makes sense.  But of course this is just my opinion of it.  I''d have to give it a 4 personally.</td>', 'Wish I knew what all kinds of cheese these were.   Hope I can explain this so you can understand.  It''s a little "dull", making it appear dark when it is not dark.  The colors are all dead or dull colors starting with the table.  To have gotten all of the wine bottle, the only thing with any life in the color, in you would have added more dead empty space in the top right corner.  It''s not that it''s a bad photo, it''s just not a really good photo, in spite of the good technical qualities you have.  I hope this makes sense.  But of course this is just my opinion of it.  I''d have to give it a 4 personally.', '2003-01-20 17:07:02.000000', NULL, 1),
(196096, 11204, 3032, '<td valign="top">Oh my god! I hit the previous vote button and bang, an explosion of taste, right in my face. Damnit, damnit, damnit, I was supposed to go easy on the cheese this year, somebody stop me!<br/>Seriously, this makes my mouth water. Good wine, good bread and good cheese, preferably in a nice location. What more can one wish?<br/> <br/>I like the composition, very good exposure, good choice of aperture for the depth. The background is nice, it looks like we are in a shed out on the country side, did some hard labour and are now going to enjoy a very good lunch. :)<br/> <br/>Wish I was there! ;) <br/>10, and favourite!</td>', 'Oh my god! I hit the previous vote button and bang, an explosion of taste, right in my face. Damnit, damnit, damnit, I was supposed to go easy on the cheese this year, somebody stop me!Seriously, this makes my mouth water. Good wine, good bread and good cheese, preferably in a nice location. What more can one wish? I like the composition, very good exposure, good choice of aperture for the depth. The background is nice, it looks like we are in a shed out on the country side, did some hard labour and are now going to enjoy a very good lunch. :) Wish I was there! ;) 10, and favourite!', '2003-01-20 17:09:01.000000', NULL, 1),
(196107, 11236, 4648, '<td valign="top">AWESOME photo.  Love the light.  Sorry about the allergy.  Beautiful combination of colors.  Love the cup and saucer and the setting.  Great job.  Should be in there.  It''s get my 10.</td>', 'AWESOME photo.  Love the light.  Sorry about the allergy.  Beautiful combination of colors.  Love the cup and saucer and the setting.  Great job.  Should be in there.  It''s get my 10.', '2003-01-20 17:14:29.000000', NULL, 1),
(196114, 11321, 4648, '<td valign="top">Should have been in better focus.  My opinion, and I''m sticking with it.  Should have seen the cheese for those that didn''t recognize it without the title.  That''s my story and I''m sticking with it.  Hope you got my humor.</td>', 'Should have been in better focus.  My opinion, and I''m sticking with it.  Should have seen the cheese for those that didn''t recognize it without the title.  That''s my story and I''m sticking with it.  Hope you got my humor.', '2003-01-20 17:16:51.000000', NULL, 1),
(196116, 11171, 4648, '<td valign="top">Cute.</td>', 'Cute.', '2003-01-20 17:17:50.000000', NULL, 1),
(196131, 11316, 4648, '<td valign="top">Can''t quite figure this one out.  The texture of the red rose looks to be over sharpened.  The rest appears to almost jump off the photo as being real, but show no signs of sharpening.  Is that the normal texture of that particular rose?  The rest of the photo looks like I can reach out and touch the flower.  That''s an awesome 10 for that.  Just don''t know about the red one.</td>', 'Can''t quite figure this one out.  The texture of the red rose looks to be over sharpened.  The rest appears to almost jump off the photo as being real, but show no signs of sharpening.  Is that the normal texture of that particular rose?  The rest of the photo looks like I can reach out and touch the flower.  That''s an awesome 10 for that.  Just don''t know about the red one.', '2003-01-20 17:22:17.000000', NULL, 1),
(196165, 11288, 327, '<td valign="top">Very nice composition, and light. The subjects are tooooooo much alike. There isn''t enough contrast to make this interesting. I think that was part of the draw back of the DAIRY challenge. Milk/cheese....all the same color. Hum, I like this shot technically. Okay -good luck.</td>', 'Very nice composition, and light. The subjects are tooooooo much alike. There isn''t enough contrast to make this interesting. I think that was part of the draw back of the DAIRY challenge. Milk/cheese....all the same color. Hum, I like this shot technically. Okay -good luck.', '2003-01-20 17:46:37.000000', NULL, 1),
(196166, 11113, 327, '<td valign="top">Looks yummy. I''ll have a large please. Nice fresh fruit this time of year....wow.<br/>I do think the light is too harsh and the berries are a bit over saturated. Might be due to the background color. Good challenge entry.</td>', 'Looks yummy. I''ll have a large please. Nice fresh fruit this time of year....wow.I do think the light is too harsh and the berries are a bit over saturated. Might be due to the background color. Good challenge entry.', '2003-01-20 17:47:44.000000', NULL, 1),
(196169, 11079, 327, '<td valign="top">Kitty.....kiddy. I love when they walk around with that drop of milk there...lol<br/>Nice attempt, but a bit OOF. 100% on challenge. Good luck.</td>', 'Kitty.....kiddy. I love when they walk around with that drop of milk there...lolNice attempt, but a bit OOF. 100% on challenge. Good luck.', '2003-01-20 17:48:53.000000', NULL, 1),
(196170, 11112, 327, '<td valign="top">I like this shot. I love the composition, and the light.....I don''t like the drops, but that''s me. This appeals to me, why....? I''m not 100% sure why. Good job for the challenge.</td>', 'I like this shot. I love the composition, and the light.....I don''t like the drops, but that''s me. This appeals to me, why....? I''m not 100% sure why. Good job for the challenge.', '2003-01-20 17:50:15.000000', NULL, 1),
(196171, 11305, 327, '<td valign="top">Heehee. Fun shooting. Lite it a little weak for me, but good composition, and focus.<br/>Nice.</td>', 'Heehee. Fun shooting. Lite it a little weak for me, but good composition, and focus.Nice.', '2003-01-20 17:50:58.000000', NULL, 1),
(196173, 11208, 327, '<td valign="top">Yum.<br/>I''m ready to eat that right now. Good capture, light, focus. Neat shot.</td>', 'Yum.I''m ready to eat that right now. Good capture, light, focus. Neat shot.', '2003-01-20 17:51:39.000000', NULL, 1),
