(199575, 11191, 885, '<td valign="top">He doesn''t look too refreshed :)  I like the stop-action quality of it, but the guy''s facial expression could probably be a little less pained.</td>', 'He doesn''t look too refreshed :)  I like the stop-action quality of it, but the guy''s facial expression could probably be a little less pained.', '2003-01-24 19:13:05.000000', NULL, 1),
(199576, 11238, 885, '<td valign="top">Different.  I like the concept of having writing at the bottom of a glass.</td>', 'Different.  I like the concept of having writing at the bottom of a glass.', '2003-01-24 19:15:43.000000', NULL, 1),
(199577, 11204, 885, '<td valign="top">Nicely done, looks almost like an ad photo.  The thing that bothers me is that that mat that the cheeses are on looks like if you tried to cut the cheese, it would all fall through the cracks.</td>', 'Nicely done, looks almost like an ad photo.  The thing that bothers me is that that mat that the cheeses are on looks like if you tried to cut the cheese, it would all fall through the cracks.', '2003-01-24 19:18:17.000000', NULL, 1),
(199578, 11080, 885, '<td valign="top">The background is nice and helps the cookie stand out well.  But the slight off-centeredness is a bit disconcerting.  It seems like it should either be centered or be more off-center so that it looks more intentional.</td>', 'The background is nice and helps the cookie stand out well.  But the slight off-centeredness is a bit disconcerting.  It seems like it should either be centered or be more off-center so that it looks more intentional.', '2003-01-24 19:21:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(199580, 11200, 885, '<td valign="top">It''s a lovely well-done photo. The background and colors and composition are quite pleasing.  But in terms of improvements, if that butter had been a little bit warmer and melting down into the cracks between the kernels, or maybe if you had used margarine (which I think may be a little bit yellower), I think it would be more appealing.  As it is now it''s pretty but makes me think of cold corn...</td>', 'It''s a lovely well-done photo. The background and colors and composition are quite pleasing.  But in terms of improvements, if that butter had been a little bit warmer and melting down into the cracks between the kernels, or maybe if you had used margarine (which I think may be a little bit yellower), I think it would be more appealing.  As it is now it''s pretty but makes me think of cold corn...', '2003-01-24 19:24:21.000000', NULL, 1),
(199582, 11112, 885, '<td valign="top">Nice white-on-white, and good composition.  Seems a little soft (?) but it could be an optical illusion because of low contrast.</td>', 'Nice white-on-white, and good composition.  Seems a little soft (?) but it could be an optical illusion because of low contrast.', '2003-01-24 19:26:10.000000', NULL, 1),
(199583, 11072, 885, '<td valign="top">Um, why is the milk grey?</td>', 'Um, why is the milk grey?', '2003-01-24 19:26:41.000000', NULL, 1),
(199585, 11305, 885, '<td valign="top">Who keeps their milk in a pitcher and makes sure all their cookies are right side up before eating them? :)</td>', 'Who keeps their milk in a pitcher and makes sure all their cookies are right side up before eating them? :)', '2003-01-24 19:29:16.000000', NULL, 1),
(199589, 11316, 885, '<td valign="top">Not sure what this is saying about modern romance.  That it gets drenched in milk?  That people treat it like cereal?  That in addition to giving roses for V-Day you should give dairy?</td>', 'Not sure what this is saying about modern romance.  That it gets drenched in milk?  That people treat it like cereal?  That in addition to giving roses for V-Day you should give dairy?', '2003-01-24 19:31:30.000000', NULL, 1),
(199728, 11233, 714, '<td valign="top">Not sure if you noticed the pink hue here.  I could be the lighting is to weak or way to strong.  She has a beautiful smile.  :-)</td>', 'Not sure if you noticed the pink hue here.  I could be the lighting is to weak or way to strong.  She has a beautiful smile.  :-)', '2003-01-25 00:57:13.000000', NULL, 1),
(199729, 11198, 714, '<td valign="top">The placement of the cow really bugs me.  I think it would have been more appealing if the cow was in the right hand corners.  The cows position is leading my eyes out of the photo.</td>', 'The placement of the cow really bugs me.  I think it would have been more appealing if the cow was in the right hand corners.  The cows position is leading my eyes out of the photo.', '2003-01-25 00:58:42.000000', NULL, 1),
